QUESTIONS.push(
{"id": "DL1-001", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "adr", "concept": "moa-norepinephrine", "tags": ["drug-list"], "stem": "Which of the following describes the mechanism of action of norepinephrine?", "options": [{"t": "α1, α2, β1 and β2 agonist", "correct": true, "why": "Table 1 lists norepinephrine as: α1, α2, β1 and β2 agonist."}, {"t": "α1 agonist", "correct": false, "why": "This is the listed mechanism of phenylephrine (α1 agonist); norepinephrine is listed as: α1, α2, β1 and β2 agonist."}, {"t": "β1 and β2 partial agonist", "correct": false, "why": "This is the listed mechanism of pindolol (β1 and β2 partial agonist); norepinephrine is listed as: α1, α2, β1 and β2 agonist."}, {"t": "α1 and α2 antagonist, irreversible", "correct": false, "why": "This is the listed mechanism of phenoxybenzamine (α1 and α2 antagonist, irreversible); norepinephrine is listed as: α1, α2, β1 and β2 agonist."}], "quote": "Norepinephrine — α1, α2, β1 and β2 agonist", "teach": "Norepinephrine: α1, α2, β1 and β2 agonist. All drugs on the Exam 1 list are reversible and competitive at their receptors except phenoxybenzamine.", "reading": [{"src": "Katzung 16e, Ch. 6", "sec": "Neurotransmitter Chemistry — Adrenergic Transmission; Table 6-2; Presynaptic Regulation (printout p. 6, 11, 15/20)", "t": "Norepinephrine (noradrenaline) is the primary transmitter released by most postganglionic sympathetic fibers, and receptors that respond to catecholamines such as norepinephrine are called adrenoceptors. Table 6-2 lists the subtypes: α1 on postsynaptic effector cells, especially smooth muscle (formation of inositol trisphosphate (IP3) and diacylglycerol (DAG), increased intracellular calcium); α2 on presynaptic adrenergic nerve terminals, platelets, lipocytes and smooth muscle (inhibition of adenylyl cyclase, decreased cyclic adenosine monophosphate (cAMP)); β1 especially on the heart and β2 especially on smooth muscle and cardiac muscle (both stimulate adenylyl cyclase and increase cAMP). The α2 receptor on noradrenergic nerve terminals is an autoreceptor: its activation by norepinephrine diminishes further norepinephrine release."}, {"src": "Katzung 16e, Ch. 2", "sec": "G Proteins & Second Messengers (printout p. 10/18)", "t": "The body responds to danger by using the catecholamines norepinephrine and epinephrine both to increase heart rate and to constrict blood vessels in the skin, acting on Gs-coupled β adrenoceptors and Gq-coupled α1 adrenoceptors respectively. A single endogenous ligand such as norepinephrine can thus bind receptors that couple to different G proteins, which lets it elicit different responses in different cells."}]},
{"id": "DL1-002", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "adr", "concept": "moa-epinephrine", "tags": ["drug-list"], "stem": "Which of the following describes the mechanism of action of epinephrine?", "options": [{"t": "α1, α2, β1 and β2 agonist", "correct": true, "why": "Table 1 lists epinephrine as: α1, α2, β1 and β2 agonist."}, {"t": "β2 partial agonist", "correct": false, "why": "This is the listed mechanism of albuterol (β2 partial agonist); epinephrine is listed as: α1, α2, β1 and β2 agonist."}, {"t": "α1 agonist", "correct": false, "why": "This is the listed mechanism of phenylephrine (α1 agonist); epinephrine is listed as: α1, α2, β1 and β2 agonist."}, {"t": "α1 and α2 antagonist, irreversible", "correct": false, "why": "This is the listed mechanism of phenoxybenzamine (α1 and α2 antagonist, irreversible); epinephrine is listed as: α1, α2, β1 and β2 agonist."}], "quote": "Epinephrine — α1, α2, β1 and β2 agonist", "teach": "Epinephrine: α1, α2, β1 and β2 agonist. All drugs on the Exam 1 list are reversible and competitive at their receptors except phenoxybenzamine.", "reading": [{"src": "Katzung 16e, Ch. 6", "sec": "Neurotransmitter Chemistry — Adrenergic Transmission; Table 6-2; Table 6-4 (printout p. 6, 8, 11, 16/20)", "t": "Adrenal medullary cells, which are embryologically analogous to postganglionic sympathetic neurons, receive input from preganglionic sympathetic nerves and release a mixture of epinephrine and norepinephrine into the circulation; in the adrenal medulla some norepinephrine is converted to epinephrine. Epinephrine is a catecholamine, and the receptors that respond to catecholamines are the adrenoceptors of Table 6-2: α1 (formation of inositol trisphosphate and diacylglycerol, increased intracellular calcium), α2 (inhibition of adenylyl cyclase, decreased cyclic adenosine monophosphate (cAMP)), and β1 and β2 (stimulation of adenylyl cyclase, increased cAMP). Table 6-4 also lists epinephrine acting at presynaptic β2 receptors with an excitatory effect on transmitter release from adrenergic and somatic motor cholinergic terminals."}, {"src": "Katzung 16e, Ch. 2", "sec": "G Proteins & Second Messengers (printout p. 10/18)", "t": "The body responds to danger by using the catecholamines norepinephrine and epinephrine both to increase heart rate and to constrict blood vessels in the skin, acting on Gs-coupled β adrenoceptors and Gq-coupled α1 adrenoceptors respectively. A single endogenous ligand such as norepinephrine can thus bind receptors that couple to different G proteins, which lets it elicit different responses in different cells."}]},
{"id": "DL1-003", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "chol", "concept": "moa-acetylcholine", "tags": ["drug-list"], "stem": "Acetylcholine is an agonist at which receptors?", "options": [{"t": "M1, M2, M3, Nn and Nm", "correct": true, "why": "Table 1: agonist at muscarinic receptors (M1, M2, M3) and nicotinic receptors (Nn, Nm)."}, {"t": "M1, M2 and M3 only", "correct": false, "why": "Leaves out the nicotinic receptors; M1, M2 and M3 are the receptors tropicamide blocks."}, {"t": "Nn only", "correct": false, "why": "Nn is the receptor at which varenicline is a partial agonist; acetylcholine acts at all five listed receptors."}, {"t": "Nn and Nm only", "correct": false, "why": "Leaves out the muscarinic receptors M1, M2 and M3."}, {"t": "M1, M2, M3, Nn, Nm, H1 and H2", "correct": false, "why": "H1 and H2 are the receptors listed for histamine, not acetylcholine."}], "teach": "Acetylcholine is the agonist at both cholinergic receptor families on the list: muscarinic (M1, M2, M3) and nicotinic (Nn, Nm). Tropicamide blocks the muscarinic receptors and varenicline is a partial agonist at Nn.", "quote": "Acetylcholine — Agonist at muscarinic receptors (M1, M2, M3) and nicotinic receptors (Nn, Nm)", "reading": [{"src": "Katzung 16e, Ch. 6", "sec": "Autonomic Receptors, Table 6-2 (printout p. 11/20)", "t": "Cholinoceptor denotes any receptor, muscarinic or nicotinic, that responds to acetylcholine; the two subtypes were named after the alkaloids muscarine and nicotine originally used to identify them. Table 6-2 places M1 on central nervous system (CNS) neurons, sympathetic postganglionic neurons and some presynaptic sites (formation of inositol trisphosphate and diacylglycerol, increased intracellular calcium), M2 on myocardium, smooth muscle and some presynaptic sites (opening of potassium channels, inhibition of adenylyl cyclase) and M3 on exocrine glands and vessels (coupling like M1). The nicotinic receptors are NN on postganglionic neurons and some presynaptic cholinergic terminals and NM at skeletal muscle neuromuscular end plates; both are pentameric, and ligand binding opens sodium and potassium channels to depolarize the cell."}, {"src": "Katzung 16e, Ch. 2", "sec": "Ion Channels; Receptor Classes & Drug Development; Table 2-1 (printout p. 9, 11, 14/18)", "t": "Acetylcholine is the example of one chemical acting on completely different structural receptor classes: it uses ligand-gated ion channels (nicotinic acetylcholine receptors) to produce a fast excitatory postsynaptic potential within milliseconds, and it also activates a separate class of G protein-coupled receptors (muscarinic receptors) that mediate slower modulatory effects over seconds to minutes on the same neurons. In Table 2-1, muscarinic receptors couple to Gi (decreased cyclic adenosine monophosphate (cAMP), opening of cardiac potassium channels and slowed heart rate) and to Gq (increased phospholipase C, inositol trisphosphate, diacylglycerol and cytoplasmic calcium)."}]},
{"id": "DL1-004", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "chol", "concept": "moa-tropicamide", "tags": ["drug-list"], "stem": "Which of the following describes the mechanism of action of tropicamide?", "options": [{"t": "Muscarinic (M1, M2, M3) antagonist, reversible", "correct": true, "why": "Table 1 lists tropicamide as: Muscarinic (M1, M2, M3) antagonist, reversible."}, {"t": "Muscarinic (M1, M2, M3) and nicotinic (Nn, Nm) agonist", "correct": false, "why": "This is the listed mechanism of acetylcholine (muscarinic (M1, M2, M3) and nicotinic (Nn, Nm) agonist); tropicamide is listed as: Muscarinic (M1, M2, M3) antagonist, reversible."}, {"t": "Nicotinic (Nn) partial agonist", "correct": false, "why": "This is the listed mechanism of varenicline (nicotinic (Nn) partial agonist); tropicamide is listed as: Muscarinic (M1, M2, M3) antagonist, reversible."}, {"t": "Non-selective histamine receptor antagonist", "correct": false, "why": "This is the listed mechanism of diphenhydramine (non-selective histamine receptor antagonist); tropicamide is listed as: Muscarinic (M1, M2, M3) antagonist, reversible."}], "quote": "Tropicamide — Muscarinic (M1, M2, M3) antagonist, reversible", "teach": "Tropicamide blocks muscarinic M1, M2 and M3 receptors, the receptors at which acetylcholine is an agonist.", "reading": [{"src": "Katzung 16e, Ch. 6", "sec": "Autonomic Receptors, Table 6-2; Box: Pharmacology of the Eye (printout p. 11, 19/20)", "t": "Table 6-2 places M1 receptors on central nervous system (CNS) neurons, sympathetic postganglionic neurons and some presynaptic sites, where ligand binding forms inositol trisphosphate (IP3) and diacylglycerol (DAG) and raises intracellular calcium; M2 on myocardium, smooth muscle and some presynaptic sites, where binding opens potassium channels and inhibits adenylyl cyclase; and M3 on exocrine glands and vessels (smooth muscle and endothelium), coupling like M1. In the eye, parasympathetic activity and muscarinic cholinomimetics contract the pupillary constrictor and ciliary muscles (M3 in Table 6-3), producing miosis and accommodation for near vision, and all of these effects are prevented or reversed by muscarinic blocking drugs."}, {"src": "Katzung 16e, Ch. 2", "sec": "Competitive & Irreversible Antagonists (printout p. 5/18)", "t": "Receptor antagonists bind to receptors but do not activate them; their primary action is to reduce the effects of agonists that normally activate the receptor. In the presence of a fixed agonist concentration, increasing concentrations of a competitive antagonist progressively inhibit the response, but sufficiently high agonist concentrations can surmount the block, so the agonist concentration-effect curve shifts to the right while its maximal effect (Emax) stays the same. The degree of inhibition therefore depends both on the antagonist concentration and on the concentration of agonist competing for the receptor."}]},
{"id": "DL1-005", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "adr", "concept": "moa-prazosin", "tags": ["drug-list"], "stem": "Which of the following describes the mechanism of action of prazosin?", "options": [{"t": "α1 antagonist, reversible", "correct": true, "why": "Table 1 lists prazosin as: α1 antagonist, reversible."}, {"t": "α1 agonist", "correct": false, "why": "This is the listed mechanism of phenylephrine (α1 agonist); prazosin is listed as: α1 antagonist, reversible."}, {"t": "α1 and α2 antagonist, irreversible", "correct": false, "why": "This is the listed mechanism of phenoxybenzamine (α1 and α2 antagonist, irreversible); prazosin is listed as: α1 antagonist, reversible."}, {"t": "β1 antagonist, reversible", "correct": false, "why": "This is the listed mechanism of metoprolol (β1 antagonist, reversible); prazosin is listed as: α1 antagonist, reversible."}], "quote": "Prazosin — α1 antagonist, reversible", "teach": "Prazosin and phenoxybenzamine both block α1. Prazosin is selective for α1 and reversible; phenoxybenzamine blocks α1 and α2 and is the only irreversible drug on the Exam 1 list.", "reading": [{"src": "Katzung 16e, Ch. 6", "sec": "Autonomic Receptors, Table 6-2; Table 6-3 (printout p. 11, 14/20)", "t": "The α1 adrenoceptor sits on postsynaptic effector cells, especially smooth muscle, and ligand binding leads to formation of inositol trisphosphate (IP3) and diacylglycerol (DAG) with increased intracellular calcium. Table 6-3 attributes to α1 the contraction of the iris radial muscle and of the gastrointestinal and bladder sphincters, and to α receptors the contraction of skin and splanchnic vessels. Within the α-adrenoceptor class, α1 and α2 receptors differ in both agonist and antagonist selectivity, and the development of more selective blocking drugs is what led to naming these subclasses."}, {"src": "Katzung 16e, Ch. 2", "sec": "Competitive & Irreversible Antagonists (printout p. 5/18)", "t": "Receptor antagonists bind to receptors but do not activate them; their primary action is to reduce the effects of agonists that normally activate the receptor. In the presence of a fixed agonist concentration, increasing concentrations of a competitive antagonist progressively inhibit the response, but sufficiently high agonist concentrations can surmount the block, so the agonist concentration-effect curve shifts to the right while its maximal effect (Emax) stays the same. The degree of inhibition therefore depends both on the antagonist concentration and on the concentration of agonist competing for the receptor."}]},
{"id": "DL1-006", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "adr", "concept": "moa-phenylephrine", "tags": ["drug-list"], "stem": "Which of the following describes the mechanism of action of phenylephrine?", "options": [{"t": "α1 agonist", "correct": true, "why": "Table 1 lists phenylephrine as: α1 agonist."}, {"t": "α1 antagonist, reversible", "correct": false, "why": "This is the listed mechanism of prazosin (α1 antagonist, reversible); phenylephrine is listed as: α1 agonist."}, {"t": "α1, α2, β1 and β2 agonist", "correct": false, "why": "This is the listed mechanism of norepinephrine and epinephrine (α1, α2, β1 and β2 agonist); phenylephrine is listed as: α1 agonist."}, {"t": "β2 partial agonist", "correct": false, "why": "This is the listed mechanism of albuterol (β2 partial agonist); phenylephrine is listed as: α1 agonist."}], "quote": "Phenylephrine — α1 agonist", "teach": "Phenylephrine is the α1-selective agonist on the list; norepinephrine and epinephrine are agonists at α1, α2, β1 and β2.", "reading": [{"src": "Katzung 16e, Ch. 6", "sec": "Box: Pharmacology of the Eye; Autonomic Receptors; Table 6-3 (printout p. 19, 11, 14/20)", "t": "Alpha adrenoceptors mediate contraction of the radially oriented pupillary dilator muscle fibers of the iris, producing mydriasis (an increase in pupil size); this occurs during sympathetic discharge and when α-agonist drugs such as phenylephrine are placed in the conjunctival sac. Table 6-3 assigns contraction of the iris radial muscle to the α1 receptor, whose ligand binding forms inositol trisphosphate (IP3) and diacylglycerol (DAG) and raises intracellular calcium (Table 6-2). Phenylephrine is also named, with noradrenaline and isoproterenol, among the agonists whose names were not practicable for naming the receptors of noradrenergic nerves, which is why the term adrenoceptor is used instead."}]},
{"id": "DL1-007", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "adr", "concept": "moa-phenoxybenzamine", "tags": ["drug-list"], "stem": "Which of the following describes the mechanism of action of phenoxybenzamine?", "options": [{"t": "α1 and α2 antagonist, irreversible", "correct": true, "why": "Table 1 lists phenoxybenzamine as: α1 and α2 antagonist, irreversible."}, {"t": "α1 antagonist, reversible", "correct": false, "why": "This is the listed mechanism of prazosin (α1 antagonist, reversible); phenoxybenzamine is listed as: α1 and α2 antagonist, irreversible."}, {"t": "β1 and β2 partial agonist", "correct": false, "why": "This is the listed mechanism of pindolol (β1 and β2 partial agonist); phenoxybenzamine is listed as: α1 and α2 antagonist, irreversible."}, {"t": "Muscarinic (M1, M2, M3) antagonist, reversible", "correct": false, "why": "This is the listed mechanism of tropicamide (muscarinic (M1, M2, M3) antagonist, reversible); phenoxybenzamine is listed as: α1 and α2 antagonist, irreversible."}], "quote": "Phenoxybenzamine — α1 and α2 antagonist, irreversible", "teach": "The drug list states that every drug on it is reversible and competitive at its receptor with one exception, phenoxybenzamine, an irreversible α1 and α2 antagonist.", "reading": [{"src": "Katzung 16e, Ch. 2", "sec": "Competitive & Irreversible Antagonists (printout p. 5-6/18)", "t": "Phenoxybenzamine is an irreversible α-adrenoceptor antagonist used to control the hypertension caused by catecholamines released from pheochromocytoma; once it lowers blood pressure, blockade is maintained even when the tumor episodically releases very large amounts of catecholamine. Noncompetitive antagonists of this kind bind the receptor irreversibly or nearly so, sometimes by a covalent bond, so agonists cannot surmount the inhibition whatever their concentration and the maximal effect of the agonist is reduced. Because such a drug need not remain present in unbound form to act, its duration of action depends on the rate of receptor turnover rather than on its own elimination, and an overdose must be antagonized physiologically with a pressor agent that does not act through α adrenoceptors."}]},
{"id": "DL1-008", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "adr", "concept": "moa-metoprolol", "tags": ["drug-list"], "stem": "Which of the following describes the mechanism of action of metoprolol?", "options": [{"t": "β1 antagonist, reversible", "correct": true, "why": "Table 1 lists metoprolol as: β1 antagonist, reversible."}, {"t": "β1 and β2 partial agonist", "correct": false, "why": "This is the listed mechanism of pindolol (β1 and β2 partial agonist); metoprolol is listed as: β1 antagonist, reversible."}, {"t": "α1 antagonist, reversible", "correct": false, "why": "This is the listed mechanism of prazosin (α1 antagonist, reversible); metoprolol is listed as: β1 antagonist, reversible."}, {"t": "α1 and α2 antagonist, irreversible", "correct": false, "why": "This is the listed mechanism of phenoxybenzamine (α1 and α2 antagonist, irreversible); metoprolol is listed as: β1 antagonist, reversible."}], "quote": "Metoprolol — β1 antagonist, reversible", "teach": "Metoprolol and pindolol both act at β receptors. Metoprolol is a β1 antagonist; pindolol is a partial agonist at β1 and β2.", "reading": [{"src": "Katzung 16e, Ch. 2", "sec": "Case Study Answer; Competitive & Irreversible Antagonists (printout p. 18, 5/18)", "t": "Metoprolol is described as a more highly selective adrenoceptor antagonist than propranolol: it binds preferentially to the β1 subtype, a major β adrenoceptor in the heart, and has a lower affinity (a higher equilibrium dissociation constant, Kd) for the β2 subtype that mediates bronchodilation, so it is an alternative for a hypertensive patient whose asthma propranolol would worsen. For a competitive β-adrenoceptor antagonist such as propranolol, the degree of inhibition depends on the antagonist concentration and on the amount of endogenous norepinephrine and epinephrine competing for the receptors, so the surge of transmitter with exercise or stress may overcome the block."}, {"src": "Katzung 16e, Ch. 6", "sec": "Autonomic Receptors, Table 6-2; Table 6-3 (printout p. 11, 14-15/20)", "t": "β1 receptors sit on postsynaptic effector cells, especially the heart, lipocytes and brain, as well as on presynaptic adrenergic and cholinergic nerve terminals and the juxtaglomerular apparatus; β2 receptors sit on postsynaptic effector cells, especially smooth muscle and cardiac muscle. Ligand binding at both stimulates adenylyl cyclase and increases cyclic adenosine monophosphate (cAMP). Table 6-3 assigns acceleration of the sinoatrial node and increased contractility to β1 and β2, renin release to β1, and relaxation of bronchiolar smooth muscle to β2."}]},
{"id": "DL1-009", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "gaba", "concept": "moa-diazepam", "tags": ["drug-list"], "stem": "Which of the following describes the mechanism of action of diazepam?", "options": [{"t": "GABA receptor allosteric agonist", "correct": true, "why": "Table 1 lists diazepam as: GABA receptor allosteric agonist."}, {"t": "Histamine H1 inverse agonist", "correct": false, "why": "This is the listed mechanism of loratadine (histamine H1 inverse agonist); diazepam is listed as: GABA receptor allosteric agonist."}, {"t": "Nicotinic (Nn) partial agonist", "correct": false, "why": "This is the listed mechanism of varenicline (nicotinic (Nn) partial agonist); diazepam is listed as: GABA receptor allosteric agonist."}, {"t": "Non-selective histamine receptor antagonist", "correct": false, "why": "This is the listed mechanism of diphenhydramine (non-selective histamine receptor antagonist); diazepam is listed as: GABA receptor allosteric agonist."}], "quote": "Diazepam — GABA receptor allosteric agonist", "teach": "Diazepam is the only drug on the list that acts at a GABA receptor, and the list classes it as an allosteric agonist.", "reading": [{"src": "Katzung 16e, Ch. 2", "sec": "Competitive & Irreversible Antagonists — allosteric modulators (printout p. 6/18)", "t": "Benzodiazepine drugs like diazepam bind to an allosteric site on ion channels that are physiologically activated by the neurotransmitter γ-aminobutyric acid (GABA); an allosteric site is a site on the receptor separate from the classical orthosteric site bound by the endogenous agonist. Benzodiazepines are termed positive allosteric modulators of GABA receptors because they potentiate, rather than inhibit, the ability of the orthosteric agonist GABA to increase channel conductance. A useful feature of this mechanism is that benzodiazepines have little activating effect on their own, which contributes to their relative safety in overdose unless combined with other sedating drugs."}], "note": "Katzung Ch. 2 calls diazepam a positive allosteric modulator of the GABA receptor, one that potentiates GABA and has little activating effect on its own; the Exam 1 drug list classes it as a GABA receptor allosteric agonist. The exam is written from the drug list."},
{"id": "DL1-010", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "adr", "concept": "moa-albuterol", "tags": ["drug-list"], "stem": "Which of the following describes the mechanism of action of albuterol?", "options": [{"t": "β2 partial agonist", "correct": true, "why": "Table 1 lists albuterol as: β2 partial agonist."}, {"t": "β1 and β2 partial agonist", "correct": false, "why": "This is the listed mechanism of pindolol (β1 and β2 partial agonist); albuterol is listed as: β2 partial agonist."}, {"t": "β1 antagonist, reversible", "correct": false, "why": "This is the listed mechanism of metoprolol (β1 antagonist, reversible); albuterol is listed as: β2 partial agonist."}, {"t": "α1, α2, β1 and β2 agonist", "correct": false, "why": "This is the listed mechanism of norepinephrine and epinephrine (α1, α2, β1 and β2 agonist); albuterol is listed as: β2 partial agonist."}], "quote": "Albuterol — β2 partial agonist", "teach": "Albuterol is a β2 partial agonist. The other β-receptor drugs on the list are pindolol (β1 and β2 partial agonist) and metoprolol (β1 antagonist).", "reading": [{"src": "Katzung 16e, Ch. 6", "sec": "Autonomic Receptors, Table 6-2; Table 6-3 (printout p. 11, 14/20)", "t": "The β2 adrenoceptor sits on postsynaptic effector cells, especially smooth muscle and cardiac muscle, and ligand binding stimulates adenylyl cyclase and increases cyclic adenosine monophosphate (cAMP); under some conditions it also activates cardiac Gi. Table 6-3 lists relaxation of bronchiolar smooth muscle, of skeletal muscle blood vessels, of the bladder wall and of the pregnant uterus as β2 effects of sympathetic activity, and acceleration of the sinoatrial node and increased contractility as β1 and β2 effects."}, {"src": "Katzung 16e, Ch. 2", "sec": "Partial Agonists (printout p. 6/18)", "t": "Agonists are divided by the maximal response they produce when all receptors are occupied: partial agonists produce a lower response at full receptor occupancy than full agonists do, and this failure to reach the full maximum is not due to decreased affinity for the receptor. Because a partial agonist occupies the same receptor sites as a full agonist, it competitively inhibits the responses produced by full agonists, a mixed agonist-antagonist property that can be beneficial or deleterious in the clinic. Full agonists tend to shift the conformational equilibrium of the receptor more strongly than partial agonists."}]},
{"id": "DL1-011", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "chol", "concept": "moa-varenicline", "tags": ["drug-list"], "stem": "Which of the following describes the mechanism of action of varenicline?", "options": [{"t": "Nicotinic (Nn) partial agonist", "correct": true, "why": "Table 1 lists varenicline as: Nicotinic (Nn) partial agonist."}, {"t": "Muscarinic (M1, M2, M3) and nicotinic (Nn, Nm) agonist", "correct": false, "why": "This is the listed mechanism of acetylcholine (muscarinic (M1, M2, M3) and nicotinic (Nn, Nm) agonist); varenicline is listed as: Nicotinic (Nn) partial agonist."}, {"t": "Muscarinic (M1, M2, M3) antagonist, reversible", "correct": false, "why": "This is the listed mechanism of tropicamide (muscarinic (M1, M2, M3) antagonist, reversible); varenicline is listed as: Nicotinic (Nn) partial agonist."}, {"t": "β2 partial agonist", "correct": false, "why": "This is the listed mechanism of albuterol (β2 partial agonist); varenicline is listed as: Nicotinic (Nn) partial agonist."}], "quote": "Varenicline — Nicotinic (Nn) partial agonist", "teach": "Varenicline is a partial agonist at the neuronal nicotinic receptor (Nn). Acetylcholine is the full agonist at both muscarinic and nicotinic receptors.", "reading": [{"src": "Katzung 16e, Ch. 6", "sec": "Autonomic Receptors, Table 6-2; Postsynaptic Regulation (printout p. 11, 16/20)", "t": "The neuronal nicotinic receptor (NN) is found on postganglionic neurons and some presynaptic cholinergic terminals; it is a pentameric receptor that typically contains α- and β-type subunits only, and ligand binding opens sodium and potassium channels, depolarizing the cell. In an autonomic ganglion, binding of an appropriate ligand to the NN receptor produces the fast excitatory postsynaptic potential that fires the postganglionic cell. NN is distinct from NM, the nicotinic receptor of skeletal muscle neuromuscular end plates, whose pentamer also contains γ and δ subunits."}, {"src": "Katzung 16e, Ch. 2", "sec": "Partial Agonists (printout p. 6/18)", "t": "Agonists are divided by the maximal response they produce when all receptors are occupied: partial agonists produce a lower response at full receptor occupancy than full agonists do, and this failure to reach the full maximum is not due to decreased affinity for the receptor. Because a partial agonist occupies the same receptor sites as a full agonist, it competitively inhibits the responses produced by full agonists, a mixed agonist-antagonist property that can be beneficial or deleterious in the clinic. Full agonists tend to shift the conformational equilibrium of the receptor more strongly than partial agonists."}]},
{"id": "DL1-012", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "hist", "concept": "moa-histamine", "tags": ["drug-list"], "stem": "Which of the following describes the mechanism of action of histamine?", "options": [{"t": "Histamine H1 and H2 agonist", "correct": true, "why": "Table 1 lists histamine as: Histamine H1 and H2 agonist."}, {"t": "Histamine H1 inverse agonist", "correct": false, "why": "This is the listed mechanism of loratadine (histamine H1 inverse agonist); histamine is listed as: Histamine H1 and H2 agonist."}, {"t": "Non-selective histamine receptor antagonist", "correct": false, "why": "This is the listed mechanism of diphenhydramine (non-selective histamine receptor antagonist); histamine is listed as: Histamine H1 and H2 agonist."}, {"t": "GABA receptor allosteric agonist", "correct": false, "why": "This is the listed mechanism of diazepam (GABA receptor allosteric agonist); histamine is listed as: Histamine H1 and H2 agonist."}], "quote": "Histamine — Histamine H1 and H2 agonist", "teach": "Histamine: Histamine H1 and H2 agonist. All drugs on the Exam 1 list are reversible and competitive at their receptors except phenoxybenzamine.", "reading": [{"src": "Katzung 16e, Ch. 2", "sec": "G Proteins & Second Messengers, Table 2-1; Receptor Classes & Drug Development (printout p. 11, 14/18)", "t": "Table 2-1 lists histamine among the ligands for Gs-coupled receptors, whose effector pathway is stimulation of adenylyl cyclase and increased cyclic adenosine monophosphate (cAMP). Histamine is also given, with norepinephrine, acetylcholine and serotonin, as a biogenic amine that activates more than one receptor, each of which may activate a different G protein, and the existence of several receptor subtypes for one endogenous ligand is what creates the opportunity for subtype-selective drugs. Histamine and acetylcholine are also named as natural vasodilator agents that make vascular endothelial cells generate nitric oxide."}]},
{"id": "DL1-013", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "hist", "concept": "moa-loratadine", "tags": ["drug-list"], "stem": "Which of the following describes the mechanism of action of loratadine?", "options": [{"t": "Histamine H1 inverse agonist", "correct": true, "why": "Table 1 lists loratadine as: Histamine H1 inverse agonist."}, {"t": "Non-selective histamine receptor antagonist", "correct": false, "why": "This is the listed mechanism of diphenhydramine (non-selective histamine receptor antagonist); loratadine is listed as: Histamine H1 inverse agonist."}, {"t": "Histamine H1 and H2 agonist", "correct": false, "why": "This is the listed mechanism of histamine (histamine H1 and H2 agonist); loratadine is listed as: Histamine H1 inverse agonist."}, {"t": "Muscarinic (M1, M2, M3) antagonist, reversible", "correct": false, "why": "This is the listed mechanism of tropicamide (muscarinic (M1, M2, M3) antagonist, reversible); loratadine is listed as: Histamine H1 inverse agonist."}], "quote": "Loratadine — Histamine H1 inverse agonist", "teach": "Loratadine and diphenhydramine both oppose histamine. The list classes loratadine as an H1 inverse agonist and diphenhydramine as a non-selective histamine receptor antagonist.", "reading": [{"src": "Katzung 16e, Ch. 2", "sec": "Competitive & Irreversible Antagonists (printout p. 5/18)", "t": "Antagonists are traditionally thought to have no functional effect in the absence of an agonist, but some antagonists exhibit inverse agonist activity because they also reduce receptor activity below the basal level observed in the absence of any agonist at all. Like other antagonists, such a drug binds the receptor without activating generation of a signal and interferes with the ability of the agonist to activate it."}]},
{"id": "DL1-014", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "adr", "concept": "moa-pindolol", "tags": ["drug-list"], "stem": "Which of the following describes the mechanism of action of pindolol?", "options": [{"t": "β1 and β2 partial agonist", "correct": true, "why": "Table 1 lists pindolol as: β1 and β2 partial agonist."}, {"t": "β1 antagonist, reversible", "correct": false, "why": "This is the listed mechanism of metoprolol (β1 antagonist, reversible); pindolol is listed as: β1 and β2 partial agonist."}, {"t": "β2 partial agonist", "correct": false, "why": "This is the listed mechanism of albuterol (β2 partial agonist); pindolol is listed as: β1 and β2 partial agonist."}, {"t": "α1 and α2 antagonist, irreversible", "correct": false, "why": "This is the listed mechanism of phenoxybenzamine (α1 and α2 antagonist, irreversible); pindolol is listed as: β1 and β2 partial agonist."}], "quote": "Pindolol — β1 and β2 partial agonist", "teach": "Pindolol is one of three partial agonists on the list (with albuterol and varenicline). It acts at both β1 and β2, where metoprolol blocks β1 only.", "reading": [{"src": "Katzung 16e, Ch. 2", "sec": "Partial Agonists (printout p. 6/18)", "t": "Agonists are divided by the maximal response they produce when all receptors are occupied: partial agonists produce a lower response at full receptor occupancy than full agonists do, and this failure to reach the full maximum is not due to decreased affinity for the receptor. Because a partial agonist occupies the same receptor sites as a full agonist, it competitively inhibits the responses produced by full agonists, a mixed agonist-antagonist property that can be beneficial or deleterious in the clinic. Full agonists tend to shift the conformational equilibrium of the receptor more strongly than partial agonists."}, {"src": "Katzung 16e, Ch. 6", "sec": "Autonomic Receptors, Table 6-2; Table 6-3 (printout p. 11, 14-15/20)", "t": "β1 receptors sit on postsynaptic effector cells, especially the heart, lipocytes and brain, as well as on presynaptic adrenergic and cholinergic nerve terminals and the juxtaglomerular apparatus; β2 receptors sit on postsynaptic effector cells, especially smooth muscle and cardiac muscle. Ligand binding at both stimulates adenylyl cyclase and increases cyclic adenosine monophosphate (cAMP). Table 6-3 assigns acceleration of the sinoatrial node and increased contractility to β1 and β2, renin release to β1, and relaxation of bronchiolar smooth muscle to β2."}]},
{"id": "DL1-015", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "hist", "concept": "moa-diphenhydramine", "tags": ["drug-list"], "stem": "Which of the following describes the mechanism of action of diphenhydramine?", "options": [{"t": "Non-selective histamine receptor antagonist", "correct": true, "why": "Table 1 lists diphenhydramine as: Non-selective histamine receptor antagonist."}, {"t": "Histamine H1 inverse agonist", "correct": false, "why": "This is the listed mechanism of loratadine (histamine H1 inverse agonist); diphenhydramine is listed as: Non-selective histamine receptor antagonist."}, {"t": "Histamine H1 and H2 agonist", "correct": false, "why": "This is the listed mechanism of histamine (histamine H1 and H2 agonist); diphenhydramine is listed as: Non-selective histamine receptor antagonist."}, {"t": "Muscarinic (M1, M2, M3) antagonist, reversible", "correct": false, "why": "This is the listed mechanism of tropicamide (muscarinic (M1, M2, M3) antagonist, reversible); diphenhydramine is listed as: Non-selective histamine receptor antagonist."}], "quote": "Diphenhydramine — Non-selective histamine receptor antagonist", "teach": "Diphenhydramine is listed as a non-selective histamine receptor antagonist; loratadine is listed as an H1 inverse agonist.", "reading": [{"src": "Katzung 16e, Ch. 2", "sec": "Receptors mediate the actions of agonists and antagonists; Receptor Classes & Drug Development (printout p. 4, 14/18)", "t": "Pharmacologic antagonists bind to receptors but do not activate generation of a signal, and consequently they interfere with the ability of an agonist to activate the receptor; some of the most useful drugs in clinical medicine are antagonists. Histamine is named as a biogenic amine that activates more than one receptor subtype, each of which may activate a different G protein, and the existence of several receptor subtypes for one endogenous ligand is what makes subtype-selective drugs possible."}]},
{"id": "DL1-016", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "adr", "concept": "irreversible-drug", "tags": ["drug-list"], "stem": "Phenoxybenzamine differs from every other drug on the Exam 1 list in which way?", "options": [{"t": "It binds its receptors irreversibly", "correct": true, "why": "The list states all its drugs are reversible and competitive at their receptors, with one exception: phenoxybenzamine, which is irreversible."}, {"t": "It is a partial agonist at β receptors", "correct": false, "why": "That describes pindolol (β1 and β2) and albuterol (β2)."}, {"t": "It is selective for the α1 receptor", "correct": false, "why": "Phenoxybenzamine blocks α1 and α2. The α1-selective drugs on the list are prazosin (antagonist) and phenylephrine (agonist)."}, {"t": "It acts at an allosteric site on its receptor", "correct": false, "why": "The list gives an allosteric mechanism only for diazepam at the GABA receptor."}], "teach": "The drug list states that every drug on it is reversible and competitive at its receptor with one exception, phenoxybenzamine, an irreversible α1 and α2 antagonist.", "quote": "All drugs listed are reversible and act competitively at their receptors, with one exception: phenoxybenzamine, which is irreversible.", "reading": [{"src": "Katzung 16e, Ch. 2", "sec": "Competitive & Irreversible Antagonists (printout p. 5-6/18)", "t": "Phenoxybenzamine is an irreversible α-adrenoceptor antagonist used to control the hypertension caused by catecholamines released from pheochromocytoma; once it lowers blood pressure, blockade is maintained even when the tumor episodically releases very large amounts of catecholamine. Noncompetitive antagonists of this kind bind the receptor irreversibly or nearly so, sometimes by a covalent bond, so agonists cannot surmount the inhibition whatever their concentration and the maximal effect of the agonist is reduced. Because such a drug need not remain present in unbound form to act, its duration of action depends on the rate of receptor turnover rather than on its own elimination, and an overdose must be antagonized physiologically with a pressor agent that does not act through α adrenoceptors."}]},
{"id": "DL1-017", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "hist", "concept": "moa-loratadine", "tags": ["drug-list"], "stem": "Which drug is a histamine H1 receptor inverse agonist?", "options": [{"t": "Loratadine", "correct": true, "why": "Table 1: Loratadine — Histamine H1 inverse agonist."}, {"t": "Diphenhydramine", "correct": false, "why": "Table 1 lists diphenhydramine as: Non-selective histamine receptor antagonist."}, {"t": "Histamine", "correct": false, "why": "Table 1 lists histamine as: Histamine H1 and H2 agonist."}, {"t": "Tropicamide", "correct": false, "why": "Table 1 lists tropicamide as: Muscarinic (M1, M2, M3) antagonist, reversible."}, {"t": "Diazepam", "correct": false, "why": "Table 1 lists diazepam as: GABA receptor allosteric agonist."}], "teach": "Loratadine and diphenhydramine both oppose histamine. The list classes loratadine as an H1 inverse agonist and diphenhydramine as a non-selective histamine receptor antagonist.", "quote": "Loratadine — Histamine (H1) receptor inverse agonist", "reading": [{"src": "Katzung 16e, Ch. 2", "sec": "Competitive & Irreversible Antagonists (printout p. 5/18)", "t": "Antagonists are traditionally thought to have no functional effect in the absence of an agonist, but some antagonists exhibit inverse agonist activity because they also reduce receptor activity below the basal level observed in the absence of any agonist at all. Like other antagonists, such a drug binds the receptor without activating generation of a signal and interferes with the ability of the agonist to activate it."}]},
{"id": "DL1-018", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "chol", "concept": "moa-varenicline", "tags": ["drug-list"], "stem": "Which drug is a partial agonist at the neuronal nicotinic (Nn) receptor?", "options": [{"t": "Varenicline", "correct": true, "why": "Table 1: Varenicline — Nicotinic (Nn) partial agonist."}, {"t": "Acetylcholine", "correct": false, "why": "Table 1 lists acetylcholine as: Muscarinic (M1, M2, M3) and nicotinic (Nn, Nm) agonist."}, {"t": "Tropicamide", "correct": false, "why": "Table 1 lists tropicamide as: Muscarinic (M1, M2, M3) antagonist, reversible."}, {"t": "Albuterol", "correct": false, "why": "Table 1 lists albuterol as: β2 partial agonist."}, {"t": "Pindolol", "correct": false, "why": "Table 1 lists pindolol as: β1 and β2 partial agonist."}], "teach": "Varenicline is a partial agonist at the neuronal nicotinic receptor (Nn). Acetylcholine is the full agonist at both muscarinic and nicotinic receptors.", "quote": "Varenicline — Nicotinic receptor (Nn) partial agonist", "reading": [{"src": "Katzung 16e, Ch. 6", "sec": "Autonomic Receptors, Table 6-2; Postsynaptic Regulation (printout p. 11, 16/20)", "t": "The neuronal nicotinic receptor (NN) is found on postganglionic neurons and some presynaptic cholinergic terminals; it is a pentameric receptor that typically contains α- and β-type subunits only, and ligand binding opens sodium and potassium channels, depolarizing the cell. In an autonomic ganglion, binding of an appropriate ligand to the NN receptor produces the fast excitatory postsynaptic potential that fires the postganglionic cell. NN is distinct from NM, the nicotinic receptor of skeletal muscle neuromuscular end plates, whose pentamer also contains γ and δ subunits."}, {"src": "Katzung 16e, Ch. 2", "sec": "Partial Agonists (printout p. 6/18)", "t": "Agonists are divided by the maximal response they produce when all receptors are occupied: partial agonists produce a lower response at full receptor occupancy than full agonists do, and this failure to reach the full maximum is not due to decreased affinity for the receptor. Because a partial agonist occupies the same receptor sites as a full agonist, it competitively inhibits the responses produced by full agonists, a mixed agonist-antagonist property that can be beneficial or deleterious in the clinic. Full agonists tend to shift the conformational equilibrium of the receptor more strongly than partial agonists."}]},
{"id": "DL1-019", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "adr", "concept": "moa-phenylephrine", "tags": ["drug-list"], "stem": "Which drug is a selective α1 agonist?", "options": [{"t": "Phenylephrine", "correct": true, "why": "Table 1: Phenylephrine — α1 agonist."}, {"t": "Prazosin", "correct": false, "why": "Table 1 lists prazosin as: α1 antagonist, reversible."}, {"t": "Norepinephrine", "correct": false, "why": "Table 1 lists norepinephrine as: α1, α2, β1 and β2 agonist."}, {"t": "Phenoxybenzamine", "correct": false, "why": "Table 1 lists phenoxybenzamine as: α1 and α2 antagonist, irreversible."}, {"t": "Albuterol", "correct": false, "why": "Table 1 lists albuterol as: β2 partial agonist."}], "teach": "Phenylephrine is the α1-selective agonist on the list; norepinephrine and epinephrine are agonists at α1, α2, β1 and β2.", "quote": "Phenylephrine — α1 agonist", "reading": [{"src": "Katzung 16e, Ch. 6", "sec": "Box: Pharmacology of the Eye; Autonomic Receptors; Table 6-3 (printout p. 19, 11, 14/20)", "t": "Alpha adrenoceptors mediate contraction of the radially oriented pupillary dilator muscle fibers of the iris, producing mydriasis (an increase in pupil size); this occurs during sympathetic discharge and when α-agonist drugs such as phenylephrine are placed in the conjunctival sac. Table 6-3 assigns contraction of the iris radial muscle to the α1 receptor, whose ligand binding forms inositol trisphosphate (IP3) and diacylglycerol (DAG) and raises intracellular calcium (Table 6-2). Phenylephrine is also named, with noradrenaline and isoproterenol, among the agonists whose names were not practicable for naming the receptors of noradrenergic nerves, which is why the term adrenoceptor is used instead."}]},
{"id": "DL1-020", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "gaba", "concept": "moa-diazepam", "tags": ["drug-list"], "stem": "Which drug acts as an allosteric agonist at the GABA receptor?", "options": [{"t": "Diazepam", "correct": true, "why": "Table 1: Diazepam — GABA receptor allosteric agonist."}, {"t": "Loratadine", "correct": false, "why": "Table 1 lists loratadine as: Histamine H1 inverse agonist."}, {"t": "Varenicline", "correct": false, "why": "Table 1 lists varenicline as: Nicotinic (Nn) partial agonist."}, {"t": "Tropicamide", "correct": false, "why": "Table 1 lists tropicamide as: Muscarinic (M1, M2, M3) antagonist, reversible."}, {"t": "Metoprolol", "correct": false, "why": "Table 1 lists metoprolol as: β1 antagonist, reversible."}], "teach": "Diazepam is the only drug on the list that acts at a GABA receptor, and the list classes it as an allosteric agonist.", "quote": "Diazepam — GABA receptor allosteric agonist", "reading": [{"src": "Katzung 16e, Ch. 2", "sec": "Competitive & Irreversible Antagonists — allosteric modulators (printout p. 6/18)", "t": "Benzodiazepine drugs like diazepam bind to an allosteric site on ion channels that are physiologically activated by the neurotransmitter γ-aminobutyric acid (GABA); an allosteric site is a site on the receptor separate from the classical orthosteric site bound by the endogenous agonist. Benzodiazepines are termed positive allosteric modulators of GABA receptors because they potentiate, rather than inhibit, the ability of the orthosteric agonist GABA to increase channel conductance. A useful feature of this mechanism is that benzodiazepines have little activating effect on their own, which contributes to their relative safety in overdose unless combined with other sedating drugs."}], "note": "Katzung Ch. 2 calls diazepam a positive allosteric modulator of the GABA receptor, one that potentiates GABA and has little activating effect on its own; the Exam 1 drug list classes it as a GABA receptor allosteric agonist. The exam is written from the drug list."},
{"id": "DL1-021", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "adr", "concept": "moa-metoprolol", "tags": ["drug-list"], "stem": "Which drug is a reversible β1 antagonist?", "options": [{"t": "Metoprolol", "correct": true, "why": "Table 1: Metoprolol — β1 antagonist, reversible."}, {"t": "Pindolol", "correct": false, "why": "Table 1 lists pindolol as: β1 and β2 partial agonist."}, {"t": "Albuterol", "correct": false, "why": "Table 1 lists albuterol as: β2 partial agonist."}, {"t": "Prazosin", "correct": false, "why": "Table 1 lists prazosin as: α1 antagonist, reversible."}, {"t": "Phenoxybenzamine", "correct": false, "why": "Table 1 lists phenoxybenzamine as: α1 and α2 antagonist, irreversible."}], "teach": "Metoprolol and pindolol both act at β receptors. Metoprolol is a β1 antagonist; pindolol is a partial agonist at β1 and β2.", "quote": "Metoprolol — β1 antagonist (reversible)", "reading": [{"src": "Katzung 16e, Ch. 2", "sec": "Case Study Answer; Competitive & Irreversible Antagonists (printout p. 18, 5/18)", "t": "Metoprolol is described as a more highly selective adrenoceptor antagonist than propranolol: it binds preferentially to the β1 subtype, a major β adrenoceptor in the heart, and has a lower affinity (a higher equilibrium dissociation constant, Kd) for the β2 subtype that mediates bronchodilation, so it is an alternative for a hypertensive patient whose asthma propranolol would worsen. For a competitive β-adrenoceptor antagonist such as propranolol, the degree of inhibition depends on the antagonist concentration and on the amount of endogenous norepinephrine and epinephrine competing for the receptors, so the surge of transmitter with exercise or stress may overcome the block."}, {"src": "Katzung 16e, Ch. 6", "sec": "Autonomic Receptors, Table 6-2; Table 6-3 (printout p. 11, 14-15/20)", "t": "β1 receptors sit on postsynaptic effector cells, especially the heart, lipocytes and brain, as well as on presynaptic adrenergic and cholinergic nerve terminals and the juxtaglomerular apparatus; β2 receptors sit on postsynaptic effector cells, especially smooth muscle and cardiac muscle. Ligand binding at both stimulates adenylyl cyclase and increases cyclic adenosine monophosphate (cAMP). Table 6-3 assigns acceleration of the sinoatrial node and increased contractility to β1 and β2, renin release to β1, and relaxation of bronchiolar smooth muscle to β2."}]},
{"id": "DL1-022", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "chol", "concept": "moa-tropicamide", "tags": ["drug-list"], "stem": "Which drug is a reversible antagonist at muscarinic M1, M2 and M3 receptors?", "options": [{"t": "Tropicamide", "correct": true, "why": "Table 1: Tropicamide — Muscarinic (M1, M2, M3) antagonist, reversible."}, {"t": "Acetylcholine", "correct": false, "why": "Table 1 lists acetylcholine as: Muscarinic (M1, M2, M3) and nicotinic (Nn, Nm) agonist."}, {"t": "Varenicline", "correct": false, "why": "Table 1 lists varenicline as: Nicotinic (Nn) partial agonist."}, {"t": "Diphenhydramine", "correct": false, "why": "Table 1 lists diphenhydramine as: Non-selective histamine receptor antagonist."}, {"t": "Prazosin", "correct": false, "why": "Table 1 lists prazosin as: α1 antagonist, reversible."}], "teach": "Tropicamide blocks muscarinic M1, M2 and M3 receptors, the receptors at which acetylcholine is an agonist.", "quote": "Tropicamide — Muscarinic (M1, M2, M3) antagonist (reversible)", "reading": [{"src": "Katzung 16e, Ch. 6", "sec": "Autonomic Receptors, Table 6-2; Box: Pharmacology of the Eye (printout p. 11, 19/20)", "t": "Table 6-2 places M1 receptors on central nervous system (CNS) neurons, sympathetic postganglionic neurons and some presynaptic sites, where ligand binding forms inositol trisphosphate (IP3) and diacylglycerol (DAG) and raises intracellular calcium; M2 on myocardium, smooth muscle and some presynaptic sites, where binding opens potassium channels and inhibits adenylyl cyclase; and M3 on exocrine glands and vessels (smooth muscle and endothelium), coupling like M1. In the eye, parasympathetic activity and muscarinic cholinomimetics contract the pupillary constrictor and ciliary muscles (M3 in Table 6-3), producing miosis and accommodation for near vision, and all of these effects are prevented or reversed by muscarinic blocking drugs."}, {"src": "Katzung 16e, Ch. 2", "sec": "Competitive & Irreversible Antagonists (printout p. 5/18)", "t": "Receptor antagonists bind to receptors but do not activate them; their primary action is to reduce the effects of agonists that normally activate the receptor. In the presence of a fixed agonist concentration, increasing concentrations of a competitive antagonist progressively inhibit the response, but sufficiently high agonist concentrations can surmount the block, so the agonist concentration-effect curve shifts to the right while its maximal effect (Emax) stays the same. The degree of inhibition therefore depends both on the antagonist concentration and on the concentration of agonist competing for the receptor."}]},
{"id": "DL1-023", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "gen", "concept": "partial-agonists", "tags": ["drug-list", "list"], "multi": true, "stem": "Which drugs on the Exam 1 list are partial agonists? Select all that apply.", "options": [{"t": "Albuterol", "correct": true, "why": "Table 1: Albuterol — β2 partial agonist."}, {"t": "Varenicline", "correct": true, "why": "Table 1: Varenicline — Nicotinic (Nn) partial agonist."}, {"t": "Pindolol", "correct": true, "why": "Table 1: Pindolol — β1 and β2 partial agonist."}, {"t": "Metoprolol", "correct": false, "why": "Table 1 lists metoprolol as: β1 antagonist, reversible."}, {"t": "Loratadine", "correct": false, "why": "Table 1 lists loratadine as: Histamine H1 inverse agonist."}, {"t": "Phenylephrine", "correct": false, "why": "Table 1 lists phenylephrine as: α1 agonist."}], "teach": "Three drugs on the list are partial agonists: albuterol (β2), varenicline (Nn) and pindolol (β1 and β2). Loratadine is an inverse agonist, metoprolol an antagonist, phenylephrine a full α1 agonist.", "quote": "Albuterol — β2 partial agonist · Varenicline — Nn partial agonist · Pindolol — β1 and β2 partial agonist", "reading": [{"src": "Katzung 16e, Ch. 2", "sec": "Partial Agonists (printout p. 6/18)", "t": "Agonists are divided by the maximal response they produce when all receptors are occupied: partial agonists produce a lower response at full receptor occupancy than full agonists do, and this failure to reach the full maximum is not due to decreased affinity for the receptor. Because a partial agonist occupies the same receptor sites as a full agonist, it competitively inhibits the responses produced by full agonists, a mixed agonist-antagonist property that can be beneficial or deleterious in the clinic. Full agonists tend to shift the conformational equilibrium of the receptor more strongly than partial agonists."}, {"src": "Katzung 16e, Ch. 2", "sec": "Relation Between Drug Dose & Clinical Response — Potency; Maximal efficacy (printout p. 15/18)", "t": "In Figure 2-15, drug B is a partial agonist: it is more potent than drug A because its half-maximal effective concentration (EC50) is lower, yet some doses of drug A produce larger effects than any dose of drug B, because drug A has the greater maximal efficacy. Maximal efficacy may be set by the drug’s mode of interaction with receptors, as with partial agonists, or by the receptor-effector system."}]},
{"id": "DL1-024", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "adr", "concept": "alpha1-drugs", "tags": ["drug-list", "list"], "multi": true, "stem": "Which drugs on the Exam 1 list act at the α1 receptor? Select all that apply.", "options": [{"t": "Norepinephrine", "correct": true, "why": "Table 1: Norepinephrine — α1, α2, β1 and β2 agonist."}, {"t": "Prazosin", "correct": true, "why": "Table 1: Prazosin — α1 antagonist, reversible."}, {"t": "Phenylephrine", "correct": true, "why": "Table 1: Phenylephrine — α1 agonist."}, {"t": "Phenoxybenzamine", "correct": true, "why": "Table 1: Phenoxybenzamine — α1 and α2 antagonist, irreversible."}, {"t": "Metoprolol", "correct": false, "why": "Table 1 lists metoprolol as: β1 antagonist, reversible."}, {"t": "Albuterol", "correct": false, "why": "Table 1 lists albuterol as: β2 partial agonist."}], "teach": "Five rows name α1: norepinephrine and epinephrine (agonists at α1, α2, β1, β2), phenylephrine (α1 agonist), prazosin (α1 antagonist) and phenoxybenzamine (α1 and α2 antagonist, irreversible). Metoprolol and albuterol act at β receptors only.", "quote": "Prazosin — α1 antagonist · Phenylephrine — α1 agonist · Phenoxybenzamine — α1 and α2 antagonist", "reading": [{"src": "Katzung 16e, Ch. 6", "sec": "Autonomic Receptors, Table 6-2; Table 6-3 (printout p. 11, 14/20)", "t": "The α1 adrenoceptor sits on postsynaptic effector cells, especially smooth muscle, and ligand binding leads to formation of inositol trisphosphate (IP3) and diacylglycerol (DAG) with increased intracellular calcium. Table 6-3 attributes to α1 the contraction of the iris radial muscle and of the gastrointestinal and bladder sphincters, and to α receptors the contraction of skin and splanchnic vessels. Within the α-adrenoceptor class, α1 and α2 receptors differ in both agonist and antagonist selectivity, and the development of more selective blocking drugs is what led to naming these subclasses."}, {"src": "Katzung 16e, Ch. 2", "sec": "G Proteins & Second Messengers (printout p. 10/18)", "t": "The body responds to danger by using the catecholamines norepinephrine and epinephrine both to increase heart rate and to constrict blood vessels in the skin, acting on Gs-coupled β adrenoceptors and Gq-coupled α1 adrenoceptors respectively. A single endogenous ligand such as norepinephrine can thus bind receptors that couple to different G proteins, which lets it elicit different responses in different cells."}]},
{"id": "DL1-025", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "gen", "concept": "antagonists-list", "tags": ["drug-list", "list"], "multi": true, "stem": "Which drugs on the Exam 1 list are antagonists? Select all that apply.", "options": [{"t": "Tropicamide", "correct": true, "why": "Table 1: Tropicamide — Muscarinic (M1, M2, M3) antagonist, reversible."}, {"t": "Prazosin", "correct": true, "why": "Table 1: Prazosin — α1 antagonist, reversible."}, {"t": "Metoprolol", "correct": true, "why": "Table 1: Metoprolol — β1 antagonist, reversible."}, {"t": "Diphenhydramine", "correct": true, "why": "Table 1: Diphenhydramine — Non-selective histamine receptor antagonist."}, {"t": "Loratadine", "correct": false, "why": "Table 1 lists loratadine as: Histamine H1 inverse agonist."}, {"t": "Pindolol", "correct": false, "why": "Table 1 lists pindolol as: β1 and β2 partial agonist."}, {"t": "Diazepam", "correct": false, "why": "Table 1 lists diazepam as: GABA receptor allosteric agonist."}], "teach": "The antagonists on the list are tropicamide, prazosin, phenoxybenzamine, metoprolol and diphenhydramine. Loratadine is classed as an inverse agonist, pindolol as a partial agonist and diazepam as an allosteric agonist.", "quote": "Tropicamide, prazosin, phenoxybenzamine, metoprolol, diphenhydramine: antagonist rows of Table 1", "reading": [{"src": "Katzung 16e, Ch. 2", "sec": "Receptors mediate the actions of agonists and antagonists; Competitive & Irreversible Antagonists (printout p. 4-6/18)", "t": "Agonists activate the receptor to signal as a direct result of binding to it; pharmacologic antagonists bind to receptors but do not activate generation of a signal and consequently interfere with the ability of an agonist to activate the receptor. Antagonists are divided into competitive antagonists, whose block can be surmounted by a high enough agonist concentration, and noncompetitive antagonists, which often bind irreversibly so that the block cannot be surmounted and the maximal response falls. Some antagonists also show inverse agonist activity, reducing receptor activity below basal levels, and drugs that bind a site different from the one bound by the endogenous ligand act as allosteric modulators."}]},
{"id": "DL1-026", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "hist", "concept": "histamine-drugs", "tags": ["drug-list", "list"], "multi": true, "stem": "Which drugs on the Exam 1 list act at histamine receptors? Select all that apply.", "options": [{"t": "Histamine", "correct": true, "why": "Table 1: Histamine — Histamine H1 and H2 agonist."}, {"t": "Loratadine", "correct": true, "why": "Table 1: Loratadine — Histamine H1 inverse agonist."}, {"t": "Diphenhydramine", "correct": true, "why": "Table 1: Diphenhydramine — Non-selective histamine receptor antagonist."}, {"t": "Tropicamide", "correct": false, "why": "Table 1 lists tropicamide as: Muscarinic (M1, M2, M3) antagonist, reversible."}, {"t": "Diazepam", "correct": false, "why": "Table 1 lists diazepam as: GABA receptor allosteric agonist."}, {"t": "Varenicline", "correct": false, "why": "Table 1 lists varenicline as: Nicotinic (Nn) partial agonist."}], "teach": "Histamine (H1 and H2 agonist), loratadine (H1 inverse agonist) and diphenhydramine (non-selective histamine receptor antagonist) are the histamine-receptor drugs on the list.", "quote": "Histamine — H1 and H2 agonist · Loratadine — H1 inverse agonist · Diphenhydramine — non-selective histamine receptor antagonist", "reading": [{"src": "Katzung 16e, Ch. 2", "sec": "G Proteins & Second Messengers, Table 2-1; Receptor Classes & Drug Development (printout p. 11, 14/18)", "t": "Table 2-1 lists histamine among the ligands for Gs-coupled receptors, whose effector pathway is stimulation of adenylyl cyclase and increased cyclic adenosine monophosphate (cAMP). Histamine is also given, with norepinephrine, acetylcholine and serotonin, as a biogenic amine that activates more than one receptor, each of which may activate a different G protein, and the existence of several receptor subtypes for one endogenous ligand is what creates the opportunity for subtype-selective drugs. Histamine and acetylcholine are also named as natural vasodilator agents that make vascular endothelial cells generate nitric oxide."}]},
{"id": "DL1-027", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "adr", "concept": "beta-drugs", "tags": ["drug-list", "list"], "multi": true, "stem": "Which drugs on the Exam 1 list act at β2 receptors? Select all that apply.", "options": [{"t": "Epinephrine", "correct": true, "why": "Table 1: Epinephrine — α1, α2, β1 and β2 agonist."}, {"t": "Albuterol", "correct": true, "why": "Table 1: Albuterol — β2 partial agonist."}, {"t": "Pindolol", "correct": true, "why": "Table 1: Pindolol — β1 and β2 partial agonist."}, {"t": "Metoprolol", "correct": false, "why": "Table 1 lists metoprolol as: β1 antagonist, reversible."}, {"t": "Phenylephrine", "correct": false, "why": "Table 1 lists phenylephrine as: α1 agonist."}, {"t": "Prazosin", "correct": false, "why": "Table 1 lists prazosin as: α1 antagonist, reversible."}], "teach": "β2 appears in the rows for norepinephrine, epinephrine, albuterol and pindolol. Metoprolol is β1 only; phenylephrine and prazosin act at α1.", "quote": "Epinephrine — α1, α2, β1, β2 agonist · Albuterol — β2 partial agonist · Pindolol — β1 and β2 partial agonist", "reading": [{"src": "Katzung 16e, Ch. 6", "sec": "Autonomic Receptors, Table 6-2; Table 6-3 (printout p. 11, 14/20)", "t": "The β2 adrenoceptor sits on postsynaptic effector cells, especially smooth muscle and cardiac muscle, and ligand binding stimulates adenylyl cyclase and increases cyclic adenosine monophosphate (cAMP); under some conditions it also activates cardiac Gi. Table 6-3 lists relaxation of bronchiolar smooth muscle, of skeletal muscle blood vessels, of the bladder wall and of the pregnant uterus as β2 effects of sympathetic activity, and acceleration of the sinoatrial node and increased contractility as β1 and β2 effects."}, {"src": "Katzung 16e, Ch. 2", "sec": "G Proteins & Second Messengers; Clinical Selectivity; Case Study Answer (printout p. 10, 17-18/18)", "t": "β adrenoceptors are Gs-coupled receptors: Gs stimulates adenylyl cyclase to raise cyclic adenosine monophosphate (cAMP) when activated by hormones and neurotransmitters acting through such receptors. β1 is a major β adrenoceptor in the heart while the β2 subtype mediates bronchodilation, and x-ray crystallography shows that the orthosteric binding sites of β1 and β2 are identical, so drugs discriminate between the subtypes by differences in the vestibule they traverse to reach that site."}]}
);
